def min_time(tasks, n):
    if not tasks or not n:
        return 0

    tasks = [int(x) for x in tasks]
    tasks.sort()
    dp = [0] * len(tasks)
    dp[0] = tasks[0]

    for i in range(1, len(tasks)):
        dp[i] = tasks[i] + dp[i-1] - 1

    for i in range(1, len(tasks)):
        dp[i] = max(dp[i], dp[i-1])

    return dp[-1] + n * (len(tasks) - 1) // 2

def is_match(s: str, p: str) -> bool:
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True

    for i in range(1, len(s) + 1):
        if s[i - 1] == p[0]:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = False

    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if s[i - 1] == p[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif j == 1:
                dp[i][j] = False
            elif p[j - 2] == '*':
                dp[i][j] = dp[i][j - 2] or dp[i - 1][j]
            else:
                dp[i][j] = False

    return dp[len(s)][len(p)]

